{
  "design": {
    "theme": "chalk",
    "picture_style": "illustration"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall equal sharing and fraction notation",
      "look_at": {"kind": "picture", "shows": "Twelve counters shared between three plates"},
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Introduce the approved objectives",
      "look_at": {"kind": "none", "shows": null},
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Explain unit fractions and equal parts",
      "look_at": {"kind": "diagram", "shows": "One of four equal parts shaded"},
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Model finding a unit fraction of an amount",
      "look_at": {"kind": "diagram", "shows": "Twenty counters shared into five equal groups"},
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Practise the matching unit-fraction calculation",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1]
    },
    {
      "slide": 6,
      "does": "Build non-unit fractions from unit fractions",
      "look_at": {"kind": "diagram", "shows": "Three of four equal parts shaded"},
      "teaches": [2]
    },
    {
      "slide": 7,
      "does": "Model dividing then multiplying",
      "look_at": {"kind": "diagram", "shows": "A bar of twenty split into five parts with three shaded"},
      "teaches": [2]
    },
    {
      "slide": 8,
      "does": "Practise the matching non-unit-fraction calculation",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [2]
    },
    {
      "slide": 9,
      "does": "Correct the numerator-denominator reversal",
      "look_at": {"kind": "diagram", "shows": "Twenty-four split into four equal parts with three selected"},
      "teaches": [1, 2]
    },
    {
      "slide": 10,
      "does": "Model a fraction-of-money word problem",
      "look_at": {"kind": "diagram", "shows": "Thirty pounds split into five parts with two shaded"},
      "teaches": [3]
    },
    {
      "slide": 11,
      "does": "Solve money, quantity and measure problems",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1, 2, 3]
    },
    {
      "slide": 12,
      "does": "Apply fractions to a new setting and justify a claim",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1, 2, 3]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Fractions of amounts",
    "lead": "Recall: share 12 into 3 equal groups. What does ⅓ mean?",
    "picture": {
      "shows": "twelve counters shared equally between three plates",
      "must_see": ["three identical plates", "four counters per plate"],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "One equal part",
      "lead": "A unit fraction has a numerator of 1.",
      "points": [
        {"label": "Denominator", "text": "The bottom number tells us how many equal parts."},
        {"label": "Find one part", "text": "Divide the whole amount by the denominator."}
      ],
      "figure": {
        "kind": "fraction-shapes",
        "shows": "A whole split into four equal parts, with one part shaded.",
        "alt": "A rectangle has four equal strips; one strip is shaded.",
        "title": null,
        "shapes": [
          {"shape": "rectangle", "parts": 4, "cut": "vertical", "shaded": 1, "name": "¼"}
        ]
      }
    },
    {
      "template": "equation-hero",
      "heading": "Find ⅕ of 20",
      "lead": null,
      "formula": "20 ÷ 5 = 4",
      "points": [
        "Share 20 into 5 equal groups.",
        "⅕ of 20 is 4."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twenty counters shared equally into five groups.",
        "alt": "Five rings each contain four counters.",
        "title": null,
        "total": 20,
        "groups": 5,
        "layout": "rings",
        "show_count": "one",
        "unknown": false
      }
    },
    {
      "template": "practice",
      "heading": "Find one equal part",
      "questions": [
        "Find ⅕ of 30.",
        "Find ¼ of 28.",
        "Find ⅛ of 56."
      ],
      "instruction": "Write the division and the answer.",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "More than one equal part",
      "lead": "A non-unit fraction has a numerator greater than 1.",
      "points": [
        "Divide by the denominator to find one part.",
        "Multiply by the numerator to find the parts needed."
      ],
      "figure": {
        "kind": "fraction-shapes",
        "shows": "Three quarters consist of three equal quarter-parts.",
        "alt": "A rectangle has four equal strips; three strips are shaded.",
        "title": null,
        "shapes": [
          {"shape": "rectangle", "parts": 4, "cut": "vertical", "shaded": 3, "name": "¾"}
        ]
      }
    },
    {
      "template": "equation-hero",
      "heading": "Find ⅗ of 20",
      "lead": null,
      "formula": "20 ÷ 5 × 3 = 12",
      "points": [
        "One fifth: 20 ÷ 5 = 4",
        "Three fifths: 4 × 3 = 12",
        "⅗ of 20 is 12."
      ],
      "figure": {
        "kind": "bar-model",
        "shows": "Twenty split into five equal parts, with three parts selected.",
        "alt": "A bar of twenty has five parts of four; three parts are shaded.",
        "title": null,
        "bars": [
          {"label": null, "whole": 20, "parts": 5, "values": null, "shaded": 3, "unknown": "none", "unit": null}
        ],
        "combined": null
      }
    },
    {
      "template": "practice",
      "heading": "Find several equal parts",
      "questions": [
        "Find ⅗ of 30.",
        "Find ¾ of 28.",
        "Find ⅝ of 40."
      ],
      "instruction": "Show the division, then the multiplication.",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "Which number do we divide by?",
      "lead": "For ¾ of 24, dividing by 3 first gives 8 × 4 = 32. That cannot be right: ¾ is less than one whole.",
      "points": [
        {"label": "Correct order", "text": "24 ÷ 4 = 6, then 6 × 3 = 18."},
        {"label": "Check", "text": "Why must ¾ of 24 be less than 24?"}
      ],
      "figure": {
        "kind": "bar-model",
        "shows": "The denominator gives four equal parts; the numerator selects three.",
        "alt": "A bar of twenty-four has four parts of six, with three shaded.",
        "title": null,
        "bars": [
          {"label": null, "whole": 24, "parts": 4, "values": null, "shaded": 3, "unknown": "none", "unit": null}
        ],
        "combined": null
      }
    },
    {
      "template": "equation-hero",
      "heading": "How much does Asha spend?",
      "lead": "Asha has £30. She spends ⅖ of it on a book.",
      "formula": "30 ÷ 5 × 2 = 12",
      "points": [
        "One fifth: £30 ÷ 5 = £6",
        "Two fifths: £6 × 2 = £12",
        "Asha spends £12."
      ],
      "figure": {
        "kind": "bar-model",
        "shows": "Thirty pounds split into five equal shares, with two shares spent.",
        "alt": "A thirty-pound bar has five six-pound parts; two parts are shaded.",
        "title": null,
        "bars": [
          {"label": null, "whole": 30, "parts": 5, "values": null, "shaded": 2, "unknown": "none", "unit": "£"}
        ],
        "combined": null
      }
    },
    {
      "template": "practice",
      "heading": "Solve the problems",
      "questions": [
        "Ben has £40. He spends ⅖ of it on a game. How much does he spend?",
        "A box holds 32 pencils. ⅜ are red. How many pencils are red?",
        "A ribbon is 45 cm long. Noor cuts off ⅕ of it. How long is the piece?"
      ],
      "instruction": "Show your working. Include the unit in each answer.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Plan a school garden",
      "questions": [
        "A tray holds 36 seedlings. ⅔ are herbs. How many seedlings are herbs?",
        "A 48 m path needs edging along ¾ of its length. How many metres need edging?",
        "Stretch: Mia says, ‘⅔ of 36 is more than ¾ of 32.’ Is she right? Prove it."
      ],
      "instruction": "Calculate and explain your decisions.",
      "picture": null
    }
  ]
}
